func sendCallSite(ctx context.Context, adapter abstractions.RequestAdapter, c callSiteURL) error {
	switch c.fn {
	case "PostRequest":
		_, err := PostRequest(ctx, adapter, PostRequestConfig{APIVersion: GraphAPIBeta, Endpoint: c.endpoint, RequestBody: newTestBody()}, models.CreateDeviceCategoryFromDiscriminatorValue, nil)
		return err
	case "PostRequestNoContent":
		return PostRequestNoContent(ctx, adapter, PostRequestConfig{APIVersion: GraphAPIBeta, Endpoint: c.endpoint, RequestBody: newTestBody()})
	case "GetRequest":
		_, err := GetRequest(ctx, adapter, GetRequestConfig{APIVersion: GraphAPIBeta, Endpoint: c.endpoint, ResourceID: c.resourceID, EndpointSuffix: c.suffix}, models.CreateDeviceCategoryFromDiscriminatorValue, nil)
		return err
	case "GetRequestByResourceId":
		_, err := GetRequestByResourceId(ctx, adapter, GetRequestConfig{APIVersion: GraphAPIBeta, Endpoint: c.endpoint, ResourceIDPattern: c.pattern, ResourceID: c.resourceID, EndpointSuffix: c.suffix})
		return err
	case "PatchRequestByResourceId":
		return PatchRequestByResourceId(ctx, adapter, PatchRequestConfig{APIVersion: GraphAPIBeta, Endpoint: c.endpoint, ResourceIDPattern: c.pattern, ResourceID: c.resourceID, EndpointSuffix: c.suffix, RequestBody: newTestBody()})
	case "PutRequestByResourceId":
		return PutRequestByResourceId(ctx, adapter, PutRequestConfig{APIVersion: GraphAPIBeta, Endpoint: c.endpoint, ResourceIDPattern: c.pattern, ResourceID: c.resourceID, EndpointSuffix: c.suffix, RequestBody: newTestBody()})
	case "DeleteRequestByResourceId":
		return DeleteRequestByResourceId(ctx, adapter, DeleteRequestConfig{APIVersion: GraphAPIBeta, Endpoint: c.endpoint, ResourceIDPattern: c.pattern, ResourceID: c.resourceID, EndpointSuffix: c.suffix})
	}
	return nil
}

// TestProductionCallSiteURLs proves every production call site sends the pinned URL, so the "/{id}", "('id')" and
// no-ID formats each caller chose are preserved.
func TestProductionCallSiteURLs(t *testing.T) {
	require.Len(t, productionCallSiteURLs, 77)

	for _, c := range productionCallSiteURLs {
		t.Run(c.name, func(t *testing.T) {
			adapter, transport := newTestAdapter(t, "https://graph.microsoft.com/beta")
			var sent []string
			transport.RegisterNoResponder(func(req *http.Request) (*http.Response, error) {
				if req.Body != nil {
					_, _ = io.Copy(io.Discard, req.Body)
				}
				sent = append(sent, req.Method+" "+req.URL.String())
				resp := httpmock.NewStringResponse(http.StatusOK, `{}`)
				resp.Header.Set("Content-Type", "application/json")
				return resp, nil
			})

			require.NoError(t, sendCallSite(context.Background(), adapter, c))
			require.Equal(t, []string{c.want}, sent)
		})
	}
}
